SELECT d, g FROM (SELECT d, g, RANK() OVER (ORDER BY g DESC) AS rk FROM (SELECT CAST(o.order_at AS DATE) AS d, SUM(CASE WHEN o.currency = 'BDT' THEN o.total_bdt ELSE o.total_amount * x.bdt_per_unit END) AS g FROM orders o LEFT JOIN currency_rates x ON x.rate_date = CAST(o.order_at AS DATE) AND x.currency = o.currency WHERE o.is_deleted = FALSE AND o.status IN ('delivered', 'in_transit', 'returned') AND CAST(o.order_at AS DATE) BETWEEN DATE '2025-01-01' AND DATE '2025-12-31' GROUP BY 1) t) ranked WHERE rk = 1
